{
  "sets": [
    {
      "title": "Set 1: National Affairs, Policy & Governance",
      "questions": [
        {
          "source_id": "1",
          "evidence": "Legal action will be taken against both the current and former election officials responsible for the discrepancies found in the voter list for constituency 127 \u2013 Pilibhit, reads an official statement by the State election commission",
          "prompt": {
            "en": "Against which constituency officials did the State election commission order legal action over voter list irregularities?",
            "hi": "राज्य चुनाव आयोग ने किस निर्वाचन क्षेत्र के अधिकारियों के खिलाफ मतदाता सूची में अनियमितता को लेकर कानूनी कार्रवाई का आदेश दिया है?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Constituency 127 \u2013 Pilibhit",
                "hi": "निर्वाचन क्षेत्र 127 - पीलीभीत"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Constituency 105 \u2013 Lucknow",
                "hi": "निर्वाचन क्षेत्र 105 - लखनऊ"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Constituency 45 \u2013 Varanasi",
                "hi": "निर्वाचन क्षेत्र 45 - वाराणसी"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Constituency 88 \u2013 Kanpur",
                "hi": "निर्वाचन क्षेत्र 88 - कानपुर"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "The State election commission ordered legal action against current and former election officials over voter list discrepancies in Pilibhit.",
            "hi": "राज्य चुनाव आयोग ने पीलीभीत में मतदाता सूची की विसंगतियों पर वर्तमान और पूर्व चुनाव अधिकारियों के खिलाफ कानूनी कार्रवाई का आदेश दिया।"
          }
        },
        {
          "source_id": "3",
          "evidence": "Elections in villages where land pooling is under way have been kept pending for the time being as the government is working on a separate governance framework for the mega capital city",
          "prompt": {
            "en": "Why are local body polls kept pending in certain villages of the Amaravati capital region?",
            "hi": "अमरावती राजधानी क्षेत्र के कुछ गांवों में स्थानीय निकाय चुनाव क्यों लंबित रखे गए हैं?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Due to an ongoing severe drought in the region",
                "hi": "क्षेत्र में चल रहे गंभीर सूखे के कारण"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Because land pooling is under way and a separate governance framework is being worked on",
                "hi": "क्योंकि भूमि समूहीकरण चल रहा है और एक अलग शासन ढांचे पर काम किया जा रहा है"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Because of a lack of financial resources for conducting polls",
                "hi": "चुनाव कराने के लिए वित्तीय संसाधनों की कमी के कारण"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Due to a high court stay order on all administrative activities",
                "hi": "सभी प्रशासनिक गतिविधियों पर उच्च न्यायालय के रोक आदेश के कारण"
              }
            }
          ],
          "correct_option_id": "b",
          "explanation": {
            "en": "Elections in land-pooling villages are kept pending as a separate governance framework is being formulated for Amaravati.",
            "hi": "भूमि समूहीकरण वाले गांवों में चुनाव लंबित रखे गए हैं क्योंकि अमरावती के लिए एक अलग शासन ढांचा तैयार किया जा रहा है।"
          }
        },
        {
          "source_id": "6",
          "evidence": "Red warnings for extremely heavy rain issued for October 27 and 28; fishermen who have ventured into the sea asked to return to shore",
          "prompt": {
            "en": "What warnings were issued by the IMD for October 27 and 28 regarding the North Andhra Pradesh coast?",
            "hi": "उत्तरी आंध्र प्रदेश तट के संबंध में IMD द्वारा 27 और 28 अक्टूबर के लिए क्या चेतावनियाँ जारी की गईं?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Orange warnings for moderate winds",
                "hi": "मध्यम हवाओं के लिए नारंगी चेतावनी"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Yellow warnings for high temperatures",
                "hi": "उच्च तापमान के लिए पीली चेतावनी"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Red warnings for extremely heavy rain",
                "hi": "अत्यधिक भारी बारिश के लिए लाल चेतावनी"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Blue warnings for coastal flooding",
                "hi": "तटीय बाढ़ के लिए नीली चेतावनी"
              }
            }
          ],
          "correct_option_id": "c",
          "explanation": {
            "en": "Red warnings for extremely heavy rain were issued for October 27 and 28 along the coast.",
            "hi": "तट के साथ 27 और 28 अक्टूबर के लिए अत्यधिक भारी बारिश की लाल चेतावनी जारी की गई थी।"
          }
        },
        {
          "source_id": "11",
          "evidence": "Periodic Labour Force Survey will include additional questions to measure labour underutilisation",
          "prompt": {
            "en": "What does the government plan to include in the Periodic Labour Force Survey to capture new categories?",
            "hi": "नई श्रेणियों को शामिल करने के लिए सरकार आवधिक श्रम बल सर्वेक्षण (PLFS) में क्या शामिल करने की योजना बना रही है?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Additional questions to measure labour underutilisation",
                "hi": "श्रम अल्पउपयोग को मापने के लिए अतिरिक्त प्रश्न"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Mandatory corporate tax filings",
                "hi": "अनिवार्य कॉर्पोरेट कर फाइलिंग"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Global migration statistics",
                "hi": "वैश्विक प्रवास आंकड़े"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Household electricity consumption indexes",
                "hi": "घरेलू बिजली खपत सूचकांक"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "The Periodic Labour Force Survey is being modified to include additional questions for measuring labour underutilisation.",
            "hi": "श्रम अल्पउपयोग को मापने के लिए अतिरिक्त प्रश्नों को शामिल करने हेतु आवधिक श्रम बल सर्वेक्षण को संशोधित किया जा रहा है।"
          }
        },
        {
          "source_id": "15",
          "evidence": "Every cetacean in India is protected under Schedule I of the Wildlife (Protection) Act 1972, which is the same level of protection accorded to tigers and lions.",
          "prompt": {
            "en": "Under which schedule of the Wildlife (Protection) Act 1972 are all cetaceans protected in India?",
            "hi": "वन्यजीव (संरक्षण) अधिनियम 1972 की किस अनुसूची के तहत भारत में सभी सेटेशियन (व्हेल आदि) संरक्षित हैं?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Schedule III",
                "hi": "अनुसूची III"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Schedule IV",
                "hi": "अनुसूची IV"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Schedule I",
                "hi": "अनुसूची I"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Schedule II",
                "hi": "अनुसूची II"
              }
            }
          ],
          "correct_option_id": "c",
          "explanation": {
            "en": "Every cetacean in India is protected under Schedule I of the Wildlife (Protection) Act 1972.",
            "hi": "भारत में प्रत्येक सेटेशियन वन्यजीव (संरक्षण) अधिनियम 1972 की अनुसूची I के तहत संरक्षित है।"
          }
        },
        {
          "source_id": "2",
          "evidence": "CREDAI Chennai sets up anti-corruption panel, frames SOP for reporting graft",
          "prompt": {
            "en": "Which organization's Chennai chapter recently set up an anti-corruption panel and framed a standard operating procedure for reporting graft?",
            "hi": "किस संगठन के चेन्नई चैप्टर ने हाल ही में एक भ्रष्टाचार विरोधी पैनल का गठन किया और रिश्वतखोरी की रिपोर्टिंग के लिए मानक संचालन प्रक्रिया (SOP) तैयार की?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "CREDAI Chennai",
                "hi": "क्रेडाई चेन्नई"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "FICCI Chennai",
                "hi": "फिक्की चेन्नई"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "CII Tamil Nadu",
                "hi": "सीआईआई तमिलनाडु"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "ASSOCHAM South",
                "hi": "एसोचैम साउथ"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "CREDAI Chennai set up an anti-corruption panel and framed an SOP for reporting graft.",
            "hi": "क्रेडाई चेन्नई ने भ्रष्टाचार विरोधी पैनल की स्थापना की और रिश्वतखोरी की रिपोर्टिंग के लिए एक एसओपी तैयार की।"
          }
        },
        {
          "source_id": "4",
          "evidence": "36 platoons of Andhra Pradesh Special Police have been deployed as part of election bandobust",
          "prompt": {
            "en": "How many platoons of the Andhra Pradesh Special Police were deployed for local body poll bandobust?",
            "hi": "स्थानीय निकाय चुनाव बंदोबस्त के लिए आंध्र प्रदेश विशेष पुलिस की कितनी प्लाटून तैनात की गईं?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "12 platoons",
                "hi": "12 प्लाटून"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "24 platoons",
                "hi": "24 प्लाटून"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "36 platoons",
                "hi": "36 प्लाटून"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "50 platoons",
                "hi": "50 प्लाटून"
              }
            }
          ],
          "correct_option_id": "c",
          "explanation": {
            "en": "36 platoons of Andhra Pradesh Special Police were deployed as part of election bandobust.",
            "hi": "चुनाव बंदोबस्त के हिस्से के रूप में आंध्र प्रदेश स्पेशल पुलिस की 36 प्लाटून तैनात की गईं।"
          }
        },
        {
          "source_id": "5",
          "evidence": "Three arrested for allegedly stealing two-wheelers in Amberpet",
          "prompt": {
            "en": "In which locality were three individuals arrested for allegedly stealing two-wheelers?",
            "hi": "किस इलाके में दोपहिया वाहन चुराने के आरोप में तीन व्यक्तियों को गिरफ्तार किया गया?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Banjara Hills",
                "hi": "बंजारा हिल्स"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Amberpet",
                "hi": "अंबरपेट"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Secunderabad",
                "hi": "सिकंदराबाद"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Jubilee Hills",
                "hi": "जुबली हिल्स"
              }
            }
          ],
          "correct_option_id": "b",
          "explanation": {
            "en": "Three persons were arrested for allegedly stealing two-wheelers in Amberpet.",
            "hi": "अंबरपेट में दोपहिया वाहन चुराने के आरोप में तीन लोगों को गिरफ्तार किया गया।"
          }
        },
        {
          "source_id": "18",
          "evidence": "US Secretary of State Marco Rubio pushed a business and energy agenda over diplomacy on his second trip to India this year.",
          "prompt": {
            "en": "During his second trip to India, what agenda did US Secretary of State Marco Rubio prioritize over diplomacy?",
            "hi": "भारत की अपनी दूसरी यात्रा के दौरान, अमेरिकी विदेश मंत्री मार्को रुबियो ने कूटनीति के मुकाबले किस एजेंडे को प्राथमिकता दी?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "A business and energy agenda",
                "hi": "व्यापार और ऊर्जा एजेंडा"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "A climate change and carbon tax treaty",
                "hi": "जलवायु परिवर्तन और कार्बन कर संधि"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "A regional military pact",
                "hi": "क्षेत्रीय सैन्य समझौता"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "A cultural exchange program",
                "hi": "सांस्कृतिक आदान-प्रदान कार्यक्रम"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "Marco Rubio pushed a business and energy agenda over diplomacy during his second trip to India.",
            "hi": "मार्को रुबियो ने भारत की अपनी दूसरी यात्रा के दौरान कूटनीति पर व्यापार और ऊर्जा एजेंडे को प्राथमिकता दी।"
          }
        },
        {
          "source_id": "20",
          "evidence": "The attack on Shroff has revived memories of the 1990s, when gangsters wielded influence over the industry.",
          "prompt": {
            "en": "An attack on which actor was reported as a dark reminder of Bollywood's gangster past in the 1990s?",
            "hi": "किस अभिनेता पर हुआ हमला 1990 के दशक के बॉलीवुड के गैंगस्टर अतीत की एक गंभीर याद के रूप में रिपोर्ट किया गया?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Ranveer Singh",
                "hi": "रणवीर सिंह"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Tiger Shroff",
                "hi": "टाइगर श्रॉफ"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Varun Dhawan",
                "hi": "वरुण धवन"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Shahid Kapoor",
                "hi": "शाहिद कपूर"
              }
            }
          ],
          "correct_option_id": "b",
          "explanation": {
            "en": "The attack on actor Tiger Shroff revived memories of 1990s Bollywood gangster influence.",
            "hi": "अभिनेता टाइगर श्रॉफ पर हुए हमले ने 1990 के दशक के बॉलीवुड के गैंगस्टर प्रभाव की यादों को ताजा कर दिया।"
          }
        },
        {
          "source_id": "21",
          "evidence": "V Harish, who ran the hugely popular Instagram account \"Finance with Harish\", was found dead on Tuesday.",
          "prompt": {
            "en": "What was the name of the popular Instagram account run by V Harish, who was found dead recently?",
            "hi": "वी हरीश द्वारा संचालित लोकप्रिय इंस्टाग्राम अकाउंट का नाम क्या था, जो हाल ही में मृत पाए गए?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Wealth with Harish",
                "hi": "वेल्थ विद हरीश"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Money Talks India",
                "hi": "मनी टॉक्स इंडिया"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Finance with Harish",
                "hi": "फाइनेंस विद हरीश"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Stock Market Guru",
                "hi": "स्टॉक मार्केट गुरु"
              }
            }
          ],
          "correct_option_id": "c",
          "explanation": {
            "en": "V Harish ran the hugely popular Instagram account \"Finance with Harish\".",
            "hi": "वी हरीश बेहद लोकप्रिय इंस्टाग्राम अकाउंट \"Finance with Harish\" चलाते थे।"
          }
        },
        {
          "source_id": "23",
          "evidence": "It is the latest in a series of attacks by the Houthi movement targeting airports and other sites in the kingdom.",
          "prompt": {
            "en": "Which movement was reported to be behind the attack on a Saudi airport where an Indian national was killed?",
            "hi": "किस आंदोलन को उस सऊदी हवाई अड्डे पर हमले के पीछे बताया गया जहाँ एक भारतीय नागरिक मारा गया था?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "The Houthi movement",
                "hi": "हूथी आंदोलन"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Al-Shabaab",
                "hi": "अल-शबाब"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Hezbollah",
                "hi": "हिजबुल्लाह"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "The Taliban",
                "hi": "तालिबान"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "The attack on the Saudi airport was carried out by the Houthi movement.",
            "hi": "सऊदी हवाई अड्डे पर हमला हूथी आंदोलन द्वारा किया गया था।"
          }
        }
      ]
    },
    {
      "title": "Set 2: Economy, Business & Finance",
      "questions": [
        {
          "source_id": "7",
          "evidence": "Bharat Petroleum’s revenues spurred 29% whilst net profit declined 22.5% on a year-over-year basis in Q2",
          "prompt": {
            "en": "How did Bharat Petroleum perform in terms of revenues and net profit on a year-over-year basis in Q2?",
            "hi": "दूसरी तिमाही (Q2) में साल-दर-साल आधार पर भारत पेट्रोलियम (Bharat Petroleum) के राजस्व और शुद्ध लाभ का प्रदर्शन कैसा रहा?"
          },
          "options": [
            {
              "id": "a",
